import React from "react";
import "./Item.css";

const Item = ({ name, price, image, addToCart }) => {
  return (
    <div className="item">
      <img src={image} alt="" />

      <p>{name}</p>

      <div className="item-price">₹{price}</div>

      <button onClick={addToCart}>Add to Cart</button>
    </div>
  );
};

export default Item;
